import{z as A,x as s,o as r,c as p,q as t,j as i,D as n,d as E,s as o,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"心理账户","description":"","frontmatter":{"title":"心理账户","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mental-accounting.md","filePath":"econ/mental-accounting.md","lastUpdated":1791413859000}'),d={name:"econ/mental-accounting.md"};function C(c,a,m,h,u,D){const l=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="心理账户" tabindex="-1">心理账户 <a class="header-anchor" href="#心理账户" aria-label="Permalink to &quot;心理账户&quot;">​</a></h1><div class="epigraph"><p>钱在账户之间不流动：奖金、房价浮盈和工资被标上不同的标签，边际替代被标签切断。</p><footer>—— Thaler, Mental Accounting and Consumer Choice, Marketing Science, 1985；Thaler, Journal of Behavioral Decision Making, 1999</footer></div><p><a href="/econ/probability-weighting">上一课</a>假定一个前景、一套 \\(w\\)。本课缺口是：家庭并不把所有财富并进一个 \\(w\\)。Thaler 的心理账户把收入来源、支出类别和结算频率切开。不重写 CPT。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准预算是单一现值约束，见<a href="/econ/two-period-micro">两期</a>：一元就是一元。现场：退税更容易被花掉，房价浮盈不容易被当成消费（至少在可再融资之前），股票账户与储蓄账户的风险容忍不同。Thaler（1980, 1985）把编辑规则写成账户：当期收入账户、资产账户、未来收入账户，MPC 递减。窄框架（narrow framing）是账户的风险版：每次赌局单独用前景理论评价，而不是并入总财富——Barberis、Huang 与 Thaler 后来用它解释股票参与不足。</p><p>缺口是给前景理论加上「哪些结果进同一个 \\(v\\)」，而不是再定义 \\(\\lambda\\)。</p><p><span class="marginnote">MPC（边际消费倾向）就是「每多拿到一元，立刻花掉几毛」：MPC=0.9 表示 1000 元里 900 元进商场、100 元进储蓄。心理账户的核心发现是 MPC 不由钱的大小决定，而由钱的标签决定——同样一元，换个来路就换个花法。</span></p><p><span class="marginnote">沉没成本被账户保留：票已经买了，不去就结算一笔损失。vNM 的财富只看可决策的未来，沉没成本应被忽略。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把选择写成：先归入账户，再在账户内用 \\(v\\) 评价，账户之间转移有心理成本。结算频率决定参考点何时重置：一年看一次组合与每天看一次，损失厌恶的打击次数不同——短视损失厌恶的微观零件在此。本课不校准频率。</p>',10)),(r(),i(B,null,{default:n(()=>[o(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E6%A0%87%E5%87%86%3A%20%E5%8D%95%E4%B8%80%E7%8E%B0%E5%80%BC%E9%A2%84%E7%AE%97%22%5D%20--%3E%20MA%5B%22%E5%BF%83%E7%90%86%E8%B4%A6%E6%88%B7%3A%20%E6%A0%87%E7%AD%BE%E5%88%87%E5%BC%80%22%5D%0A%20%20MA%20--%3E%20MPC%5B%22%E4%B8%8D%E5%90%8C%E6%9D%A5%E6%BA%90%E4%B8%8D%E5%90%8C%20MPC%22%5D%0A%20%20MA%20--%3E%20NF%5B%22%E7%AA%84%E6%A1%86%E6%9E%B6%3A%20%E8%B5%8C%E5%B1%80%E4%B8%8D%E5%B9%B6%E5%85%A5%E8%B4%A2%E5%AF%8C%22%5D%0A%20%20NF%20--%3E%20PART%5B%22%E5%8F%82%E4%B8%8E%E4%B8%8D%E8%B6%B3%E7%9A%84%E4%B8%80%E6%9D%A1%E9%80%9A%E9%81%93%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制是不可替代。标签把可替代的货币变成不可替代的商品。这不是新的商品空间公理，是决策者自己施加的约束，类似被需求的承诺，但动机往往不是老练自我，而是编辑习惯。住房净值进「资产账户」时，服务流仍被消费，资本利得却不进当期 MPC——与上一单元住房课的交易成本叠加，不必二选一。",-1)),a[5]||(a[5]=e("p",null,[E("与"),e("a",{href:"/econ/consumption-euler"},"欧拉"),E("的冲突是局部的：账户内仍可有平滑，账户间的转移摩擦制造过度敏感的另一种来源，与流动性约束可观测相似。")],-1)),(r(),i(B,null,{default:n(()=>[o(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20CASH%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%201000%20%E5%85%83%22%5D%20--%3E%20A%5B%22%E5%BD%93%E6%9C%9F%E6%94%B6%E5%85%A5%E8%B4%A6%E6%88%B7%EF%BC%9A%E5%B7%A5%E8%B5%84%E3%80%81%E9%80%80%E7%A8%8E%22%5D%0A%20%20CASH%20--%3E%20B%5B%22%E8%B5%84%E4%BA%A7%E8%B4%A6%E6%88%B7%EF%BC%9A%E8%82%A1%E7%A5%A8%E3%80%81%E6%88%BF%E4%BB%B7%E6%B5%AE%E7%9B%88%22%5D%0A%20%20CASH%20--%3E%20C%5B%22%E6%9C%AA%E6%9D%A5%E6%94%B6%E5%85%A5%E8%B4%A6%E6%88%B7%EF%BC%9A%E5%85%BB%E8%80%81%E9%87%91%E3%80%81%E8%BF%9C%E6%9C%9F%E5%A5%96%E9%87%91%22%5D%0A%20%20A%20--%3E%20D%5B%22MPC%20%E9%AB%98%EF%BC%9A%E5%A4%A7%E5%8D%8A%E5%BE%88%E5%BF%AB%E8%8A%B1%E6%8E%89%22%5D%0A%20%20B%20--%3E%20E%5B%22MPC%20%E4%BD%8E%EF%BC%9A%E7%95%99%E5%9C%A8%E8%B4%A6%E6%88%B7%E9%87%8C%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20C%20--%3E%20F%5B%22MPC%20%E6%9C%80%E4%BD%8E%EF%BC%9A%E5%87%A0%E4%B9%8E%E6%B0%B8%E4%B8%8D%E7%A2%B0%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">结算频率可以类比称体重：每天上秤的人，涨半斤就焦虑；一年称一次，波动被攒成一大笔再一起感受。每天看盘的投资者一年被损失厌恶打击约 250 次，一年看一次只被打击 1 次——组合的客观风险没变，变的是结算次数。</span></p><p>窄框架是账户在风险上的名字：每次股票下注单独进 \\(v\\)，总财富的 \\(u(c)\\) 不来对冲。于是公平的股权溢价在账户内仍被 \\(\\lambda\\) 拒绝，参与下降——后课短视损失厌恶把评价频率也变成账户规则。退税、红包、房价浮盈被标上不同标签时，MPC 不同，不是因为现值预算裂了，是编辑规则不许一元等于一元。</p><p><span class="marginnote">常见误区：以为「大手大脚」是性格问题。现场研究显示，同一个人对工资精打细算，对退税却在几周内花掉大半——行为随账户标签切换，跟人格无关；识别心理账户要看「标签变了、资源没变」时选择是否变。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>并非所有分类都是非理性：监督、夫妻分工、企业的成本中心，都有代理理由。识别心理账户要看标签变化而资源不变时选择是否变。本课不把公司资本预算的部门墙写成家庭理论。也不进入簿的账户（清算、保证金），那是量化栏。</p><p>后课默认：框架效应是账户与编辑的语言面；同一客观菜单，陈述不同则归入不同账户。</p><p>标签把可替代货币变成不可替代商品；一元不再等于一元，是编辑规则，不是预算裂了。</p><p>窄框架让每次赌局单独进 \\(v\\)，参与不足多一条通道。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>心理账户切断货币可替代性，MPC 随标签变。</li><li>窄框架让前景理论作用于局部赌局，加重不参与。</li><li>不重写加权函数；只问哪些结果进入同一个前景。</li><li>结算频率决定损失厌恶被打击的次数。</li><li>沉没成本被账户保留，规范模型应忽略。</li><li>出处：Thaler, 1980, 1985, 1999。</li></ul>',10))])}const T=A(d,[["render",C]]);export{P as __pageData,T as default};
